// Parse birthdays (YYYY-MM-DD, DD/MM/YYYY, DD/MM, MM-DD), find the next occurrence and keep the ones at a reminder lead time
const s = $('Set reminder settings').first().json;
const tz = s.timezone || 'Europe/London';
const leads = String(s.lead_days || '14,3,0').split(',').map(n => Number(n.trim())).filter(n => !isNaN(n));
const today = DateTime.now().setZone(tz).startOf('day');
const parse = v => {
  const t = String(v || '').trim(); let m;
  if ((m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/))) return { y: +m[1], mo: +m[2], d: +m[3] };
  if ((m = t.match(/^(\d{1,2})[\/.](\d{1,2})(?:[\/.](\d{4}))?$/))) return { y: m[3] ? +m[3] : null, mo: +m[2], d: +m[1] };
  if ((m = t.match(/^(\d{1,2})-(\d{1,2})$/))) return { y: null, mo: +m[1], d: +m[2] };
  return null;
};
const next = (mo, d) => {
  for (const y of [today.year, today.year + 1]) {
    let dt = DateTime.fromObject({ year: y, month: mo, day: d }, { zone: tz });
    if (!dt.isValid && mo === 2 && d === 29) dt = DateTime.fromObject({ year: y, month: 2, day: 28 }, { zone: tz });
    if (dt.isValid && dt >= today) return dt;
  }
  return null;
};
const out = [];
for (const p of $input.all().map(i => i.json)) {
  const name = p.name || p.displayName; const b = parse(p.birthday || p.date);
  if (!name || !b) continue;
  const when = next(b.mo, b.d); if (!when) continue;
  const days = Math.round(when.diff(today, 'days').days);
  if (!leads.includes(days)) continue;
  out.push({ json: { name, relationship: p.relationship || '', interests: p.interests || '', budget: p.budget || s.default_budget,
    notes: p.notes || '', last_gift: p.last_gift || '', email: p.email || '', occasion: p.occasion || 'birthday',
    date: when.toFormat('cccc d LLLL'), days_until: days, turning: b.y ? when.year - b.y : null,
    stage: days === 0 ? 'today' : 'gift', key: `${name}|${when.toISODate()}|${days}` } });
}
return out;

parameters.text:
=Suggest 5 thoughtful  gift ideas for {{ $json.name }} ({{ $json.relationship || 'friend' }}){{ $json.turning ? ', turning ' + $json.turning : '' }}. Their {{ $json.occasion }} is in {{ $json.days_until }} days ({{ $json.date }}), so ideas must be buyable or bookable by then.

Interests: {{ $json.interests || 'unknown: suggest broadly loved, personal-feeling gifts' }}
Budget: {{ $json.budget }} each
Notes: {{ $json.notes || 'none' }}
Gifts already given (do not repeat): {{ $json.last_gift || 'none' }}

Mix at least one experience and one practical item. price is a realistic estimate in the budget's currency. where is a type of shop (never a made-up shop name). search is a short shopping search query. card_line is one line for the card.

