const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map((item, i) => {
  const p = $('Gift reminder or birthday today?').itemMatching(i).json;
  const o = item.json.output || {};
  const q = s => encodeURIComponent(s || '');
  const lines = (o.ideas || []).slice(0, 5).map((g, n) =>
    `${n + 1}. <b>${esc(g.gift)}</b> (${esc(g.price)})\n   ${esc(g.why)}\n   <a href="https://www.google.com/search?tbm=shop&q=${q(g.search || g.gift)}">Search shops</a> · ${esc(g.where)}`);
  const text = `🎁 <b>${esc(p.name)}</b>'s ${esc(p.occasion)} is in ${p.days_until} day${p.days_until === 1 ? '' : 's'} (${esc(p.date)})${p.turning ? `, turning ${p.turning}` : ''}.\n\n${lines.join('\n\n')}\n\n💌 Card idea: <i>${esc(o.card_line)}</i>`;
  return { json: { ...p, text, ideas: (o.ideas || []).map(g => g.gift).join('; ') } };
});

